using System;using System.Linq;using UnityEngine;using UnityEditor;using LWS.TruckBowling;using LWS.TruckCornhole;using LWS.TruckCurling;using LWS.TruckKeepaway;using LWS.TruckTerrierRacing;
namespace LWS.TruckSports.Editor {
public static class SportsCabUpgradeAuthoring {
 static SportsLegacyCabLook Bind(Camera camera,Transform cockpit,int index){var link=camera.GetComponent<SportsLegacyCabLook>();if(link==null)link=camera.gameObject.AddComponent<SportsLegacyCabLook>();link.view=camera;link.viewIndex=index;link.cockpit=cockpit;var look=camera.GetComponent<SportsCabLook>();if(look==null)look=camera.gameObject.AddComponent<SportsCabLook>();link.look=look;if(cockpit!=null)cockpit.SetParent(null,true);return link;}
 static Transform Canonical(Camera camera,string folder,int index,int layer){var obsolete=camera.transform.Find("Inside tiny cab");if(obsolete!=null)UnityEngine.Object.DestroyImmediate(obsolete.gameObject);var old=camera.transform.Find("Driver seat interior");if(old!=null)UnityEngine.Object.DestroyImmediate(old.gameObject);var previous=camera.GetComponent<SportsLegacyCabLook>();if(previous!=null&&previous.cockpit!=null)UnityEngine.Object.DestroyImmediate(previous.cockpit.gameObject);SportsChaosAuthoring.Cab(camera,folder,index,layer-index);return camera.transform.Find("Driver seat interior");}
 public static void InstallScene(){if(EditorApplication.isPlaying)throw new Exception("Stopped native authoring required");var bowling=UnityEngine.Object.FindAnyObjectByType<BowlingMatch>();if(bowling!=null){foreach(var lane in bowling.lanes){LWS.TruckBowling.Editor.BowlingCabRepairAuthoring.AlignTruck(lane.truck);lane.cab.exterior=lane.truck.GetComponentsInChildren<Renderer>(true);var root=Canonical(lane.cab.view,"TruckBowling",lane.index,26+lane.index);lane.cab.view.nearClipPlane=.015f;lane.cab.interior=root.GetComponentsInChildren<Renderer>(true);var link=Bind(lane.cab.view,root,lane.index);link.bowling=lane.cab;link.steering=root.GetComponent<SportsCabSteering>();}return;}
 var corn=UnityEngine.Object.FindAnyObjectByType<CornholeMatch>();if(corn!=null){foreach(var course in corn.courses){var root=Canonical(course.chase.view,"TruckCornhole",course.index,24+course.index);course.chase.view.nearClipPlane=.015f;course.chase.interior=root.GetComponentsInChildren<Renderer>(true);var link=Bind(course.chase.view,root,course.index);link.cornhole=course.chase;link.steering=root.GetComponent<SportsCabSteering>();}return;}
 var curl=UnityEngine.Object.FindAnyObjectByType<CurlingMatch>();if(curl!=null){if(curl.cab!=null)UnityEngine.Object.DestroyImmediate(curl.cab);var root=Canonical(curl.cabCamera.view,"TruckCurling",0,26);curl.cab=root.gameObject;curl.houseCamera.cullingMask&=~(1<<26);var link=Bind(curl.cabCamera.view,root,0);link.curling=curl;link.steering=root.GetComponent<SportsCabSteering>();return;}
 var keep=UnityEngine.Object.FindAnyObjectByType<KeepawayMatch>();if(keep!=null){for(int v=0;v<keep.cabViews.Length;v++){var c=keep.cabViews[v].view;var root=c.transform.Find("Driver seat interior");if(root==null){var existing=c.GetComponent<SportsLegacyCabLook>();if(existing!=null)root=existing.cockpit;}var link=Bind(c,root,v);link.keepaway=keep;}return;}
 var terrier=UnityEngine.Object.FindAnyObjectByType<TerrierMatch>();if(terrier!=null){for(int v=0;v<terrier.cabViews.Length;v++){var c=terrier.cabViews[v].view;var root=c.transform.Find("Driver seat interior");if(root==null){var existing=c.GetComponent<SportsLegacyCabLook>();if(existing!=null)root=existing.cockpit;}var link=Bind(c,root,v);link.terrier=terrier;}}
 }
 public static void InstallSettings(SportsMenuView menu){if(menu==null||menu.pages==null)return;var page=menu.pages.FirstOrDefault(p=>p!=null&&p.name=="Settings");if(page==null)return;var info=page.transform.Find("Info");if(info!=null){var text=info.GetComponent<TMPro.TMP_Text>();text.text="RMB / right stick: look · middle / stick click: recenter\nShared sticks keep the default view.";text.rectTransform.anchoredPosition=new Vector2(350,-285);text.rectTransform.sizeDelta=new Vector2(610,42);text.fontSizeMax=18;text.fontSizeMin=16;}if(page.transform.GetComponentsInChildren<SportsMenuAction>(true).All(a=>a.action!="looksensitivity"))menu.lookSensitivityText=SportsUIAuthoring.Button(page.transform,"LOOK SENSITIVITY","looksensitivity",new Vector2(350,-150),new Vector2(550,62)).normalTextObj;else menu.lookSensitivityText=page.transform.GetComponentsInChildren<SportsMenuAction>(true).First(a=>a.action=="looksensitivity").button.normalTextObj;if(page.transform.GetComponentsInChildren<SportsMenuAction>(true).All(a=>a.action!="lookinvert"))menu.lookInvertText=SportsUIAuthoring.Button(page.transform,"LOOK Y","lookinvert",new Vector2(350,-225),new Vector2(550,62)).normalTextObj;else menu.lookInvertText=page.transform.GetComponentsInChildren<SportsMenuAction>(true).First(a=>a.action=="lookinvert").button.normalTextObj;}
}}
